<?php $this->layout('default'); use Moves\Services\CmsContent; use Moves\Support\CmsView as V; ?>
<div class="cms-grid-2"><div class="cms-card"><?php $rows = CmsContent::categories(); if ($rows === []): ?><?= V::empty('Nenhuma categoria cadastrada.') ?><?php else: ?><div class="cms-table-wrap"><table><thead><tr><th>Nome</th><th class="num">Conteúdos</th><th></th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= V::e($row['title']) ?></td><td class="num"><?= (int) $row['posts_count'] ?></td><td><?= V::actionButton('category-delete', 'Excluir', ['id' => $row['id']], 'cms-btn-danger', 'Excluir esta categoria?') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<form class="cms-card" method="post" action="/acao/category-save"><h2>Nova categoria</h2><?= V::csrf() ?><?= V::field('Nome', 'title', '', ['required' => true]) ?><?= V::field('Descrição', 'description', '', ['type' => 'textarea', 'rows' => 2]) ?><button class="cms-btn-primary">Salvar</button></form></div>
